parameters.jsCode:
const items = $input.all();
const validDeals = items.filter(i => {
  const d = i.json;
  return d.email && !d.is_unsubscribed;
});

if (validDeals.length === 0) {
  return [{
    json: {
      deal_id: 1,
      deal_name: 'Deal ERP Mẫu',
      email: 'lan.mai@vku.udn.vn',
      full_name: 'Mai Hương Lan',
      company_name: 'Đại học VKU',
      expected_budget: 60000000,
      followup_count: 1
    }
  }];
}

return validDeals;

const item = $('3. Filter Blacklisted Leads Code').item.json;
const count = Number(item.followup_count || 0);

let stage_name = 'Giai đoạn 1: Thăm dò thân mật & Gửi hồ sơ năng lực';
let email_topic = 'Tài liệu giải pháp quản trị doanh nghiệp';

if (count >= 2) {
  stage_name = 'Giai đoạn 3: Đề xuất ưu đãi giới hạn trước khi đóng deal';
  email_topic = 'Chính sách ưu đãi 15% triển khai tháng 10/2026';
} else if (count >= 1) {
  stage_name = 'Giai đoạn 2: Lời mời dùng thử và demo trực tiếp';
  email_topic = 'Mời tham gia phiên demo trải nghiệm giải pháp';
}

return [{
  json: {
    ...item,
    current_count: count,
    stage_name,
    email_topic
  }
}];

const item = $input.first().json;
const name = item.full_name || 'Quý khách';
const comp = item.company_name || 'Doanh nghiệp đối tác';

const bodyText = `Kính gửi ${name} (${comp}),

Đội ngũ NovaCRM xin phép liên hệ lại để kiểm tra xem Quý khách đã nhận được bộ tài liệu giải pháp và hồ sơ năng lực kỹ thuật mà chúng tôi đã gửi hay chưa.

Hiện tại chúng tôi đang có chương trình hỗ trợ demo thực tế hệ thống theo quy mô ngân sách ${Number(item.expected_budget || 0).toLocaleString('vi-VN')} VNĐ. Nếu Quý khách cần đặt lịch trao đổi nhanh 15 phút, xin vui lòng phản hồi email này.

Trân trọng,
Ban Chăm Sóc Khách Hàng NovaCRM`;

return [{
  json: {
    ...item,
    email_subject: `[NovaCRM] ${item.email_topic} - Hỗ trợ ${comp}`,
    email_body_html: bodyText.replace(/\n/g, '<br/>')
  }
}];

